import requests
import json
import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    try:
        response = requests.get(url, params=parameters, headers=HEADERS, timeout=10)
        response.raise_for_status()
    except Exception:
        raise Exception("Invalid URL or cannot access the URL")
    try:
        data = response.json()
    except Exception:
        raise Exception("Invalid data: cannot parse JSON")
    if not data:
        raise Exception("Empty data")
    try:
        df = pd.DataFrame(data)
    except Exception:
        raise Exception("Invalid data: cannot convert to DataFrame")
    if df.empty:
        raise Exception("Empty data")
    numeric_df = df.select_dtypes(include=['number'])
    if numeric_df.empty:
        raise Exception("Invalid data: no numerical columns")
    corr = numeric_df.corr()
    fig, ax = plt.subplots(figsize=(10, 8))
    sns.heatmap(corr, annot=True, cmap='coolwarm', ax=ax)
    return df, ax

import pandas as pd
import os
import json
from collections import Counter
def task_func(json_dir_path, word_count):
    word_counter = Counter()
    for filename in os.listdir(json_dir_path):
        if filename.endswith('.json'):
            file_path = os.path.join(json_dir_path, filename)
            with open(file_path, 'r') as f:
                try:
                    data = json.load(f)
                    text = data.get('text', '')
                    words = text.lower().split()
                    word_counter.update(words)
                except (json.JSONDecodeError, AttributeError):
                    continue
    return word_counter.most_common(word_count)

import pandas as pd
import os
import json
from collections import Counter
def task_func(json_dir_path, word_count):
    all_words = []
    for filename in os.listdir(json_dir_path):
        if filename.endswith('.json'):
            file_path = os.path.join(json_dir_path, filename)
            try:
                with open(file_path, 'r') as f:
                    data = json.load(f)
                text = data.get('text', '')
                words = text.lower().split()
                all_words.extend(words)
            except (json.JSONDecodeError, IOError):
                continue
    word_counts = Counter(all_words)
    return word_counts.most_common(word_count)

