import json
import os
def task_func(file_path: str, regex_pattern=r'\(.+?\)|\w') -> dict:
    with open(file_path, 'r') as f:
        data = json.load(f)
    matches = []
    if isinstance(data, list):
        for item in data:
            matches.extend(re.findall(regex_pattern, str(item)))
    elif isinstance(data, dict):
        for value in data.values():
            matches.extend(re.findall(regex_pattern, str(value)))
    return {os.path.basename(file_path): matches}

