import json
import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    data = json.loads(json_str)
    def clean(obj):
        if isinstance(obj, dict):
            return {k: clean(v) for k, v in obj.items() if v is not None}
        elif isinstance(obj, list):
            return [clean(v) for v in obj if v is not None]
        else:
            return obj
    data = clean(data)
    def replace_emails(obj):
        if isinstance(obj, str):
            return re.sub(r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b', REPLACE_NONE, obj)
        elif isinstance(obj, dict):
            return {k: replace_emails(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [replace_emails(v) for v in obj]
        else:
            return obj
    data = replace_emails(data)
    def flatten(obj):
        if isinstance(obj, dict):
            for v in obj.values():
                yield from flatten(v)
        elif isinstance(obj, list):
            for v in obj:
                yield from flatten(v)
        else:
            yield obj
    value_counts = Counter(flatten(data))
    return {"data": data, "value_counts": value_counts}

